mapper.insert:
insert into sys_notice_user(notice_id, user_code)
select #{noticeId}, user_code from sys_user where user_status = 1 and tenant_id = #{tenantId}
on conflict(user_code, notice_id) do nothing

insert.if:
insert into sys_notice_user(notice_id, user_code) select #{noticeId}, u.user_code from sys_user_dept d join sys_user u on d.user_id = u.user_id where u.tenant_id = #{tenantId} and u.user_status = 1 and d.dept_id in
#{deptId}
on conflict(user_code, notice_id) do nothing

insert into sys_notice_user(notice_id, user_code) select #{noticeId}, u.user_code from sys_user_role r join sys_user u on r.user_id = u.user_id where u.tenant_id = #{tenantId} and u.user_status = 1 and r.role_id in
#{roleId}
on conflict(user_code, notice_id) do nothing

insert into sys_notice_user(notice_id, user_code) select #{noticeId}, u.user_code from sys_user u where u.tenant_id = #{tenantId} and u.user_id in
#{userId}
on conflict(user_code, notice_id) do nothing
